// src/pages/customer/BookingsPage.tsx
import React, { useEffect, useState } from "react";
import styled from "styled-components";
import { useNavigate } from "react-router-dom";
import TabBar from "../../components/common/TabBar";
import BookingTile from "../../components/common/BookingTile";
import api from "../../utils/api";
import errorImage from "../../images/errorLoading.png";

/* ============================================================
   Styled Components
============================================================ */
const PageWrapper = styled.div`
  background-color: #f2dcdc;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
`;

const ContentWrapper = styled.div`
  width: 100%;
  max-width: 1600px;
  padding: 40px 0;
  display: flex;
  flex-direction: column;
  gap: 60px;
`;

const Section = styled.div`
  width: 100%;
`;

const SectionTitle = styled.h2`
  font-family: "Inter", sans-serif;
  font-size: 36px;
  font-weight: 800;
  color: #27374d;
  margin-bottom: 25px;
`;

const TilesContainer = styled.div`
  display: flex;
  flex-direction: column;
  gap: 25px;
`;

const EmptyText = styled.p`
  font-size: 15px;
  color: #555;
`;

const ErrorText = styled.p`
  font-size: 14px;
  color: red;
`;

/* ============================================================
   Types
============================================================ */
type BookingStatus = "pending" | "confirmed" | "completed" | "cancelled";

type BookingApiService = {
  _id?: string;
  name: string;
  durationMinutes: number;
  priceBHD: number;
};

type BookingApi = {
  _id: string;
  business: {
    _id?: string;
    businessName: string;
    address?: string;
    city?: string;
    profileImageUrl?: string;
  };
  services: BookingApiService[];
  startTime: string;
  status: BookingStatus;
  staffName?: string | null;
};

type BookingCard = {
  id: string;
  businessId: string;
  date: string;
  image: string;
  salonName: string;
  location: string;
  services: string[];
  status: BookingStatus;

  // extra data to support reschedule
  servicesRaw: BookingApiService[];
};

/* ============================================================
   Component
============================================================ */
const BookingsPage: React.FC = () => {
  const navigate = useNavigate();

  const [upcoming, setUpcoming] = useState<BookingCard[]>([]);
  const [past, setPast] = useState<BookingCard[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [actionLoadingId, setActionLoadingId] = useState<string | null>(null);

  useEffect(() => {
    const loadBookings = async () => {
      try {
        setLoading(true);
        setError(null);

        const res = await api.get<BookingApi[]>("/bookings/me");
        const data = res.data || [];

        const now = new Date();

        const upcomingTmp: BookingCard[] = [];
        const pastTmp: BookingCard[] = [];

        data.forEach((b) => {
          const start = new Date(b.startTime);
          const isFuture = start >= now;

          const formattedDate = start.toLocaleString(undefined, {
            weekday: "short",
            month: "short",
            day: "numeric",
            hour: "numeric",
            minute: "2-digit",
          });

          const businessId =
            (b.business && (b.business as any)._id) ||
            (b as any).businessId ||
            "";

          const card: BookingCard = {
            id: b._id,
            businessId,
            date: formattedDate,
            image: b.business?.profileImageUrl || errorImage,
            salonName: b.business?.businessName || "Unknown Salon",
            location: `${b.business?.city || ""}${
              b.business?.city && b.business?.address ? " · " : ""
            }${b.business?.address || ""}`,
            services: (b.services || []).map((s) => s.name),
            status: b.status,
            servicesRaw: b.services || [],
          };

          const isUpcoming =
            isFuture && (b.status === "pending" || b.status === "confirmed");

          if (isUpcoming) {
            upcomingTmp.push(card);
          } else {
            pastTmp.push(card);
          }
        });

        setUpcoming(upcomingTmp);
        setPast(pastTmp);
      } catch (err: any) {
        console.error("Error loading bookings", err);
        setError(
          err?.response?.data?.message || "Failed to load bookings."
        );
      } finally {
        setLoading(false);
      }
    };

    loadBookings();
  }, []);

  /* ============================================================
     Handlers: Cancel & Reschedule
  ============================================================ */

  const handleCancel = async (booking: BookingCard) => {
    if (
      !window.confirm(
        "Are you sure you want to cancel this booking?"
      )
    ) {
      return;
    }

    try {
      setActionLoadingId(booking.id);
      setError(null);

      // 🔧 If your backend uses a different endpoint/method, update here.
      // Example options:
      // await api.patch(`/bookings/${booking.id}/cancel`);
      // or
      // await api.delete(`/bookings/${booking.id}`);
      await api.patch(`/bookings/${booking.id}/cancel`);

      // Move it from upcoming → past with status "cancelled"
      setUpcoming((prev) => prev.filter((b) => b.id !== booking.id));
      setPast((prev) => [
        { ...booking, status: "cancelled" },
        ...prev,
      ]);
    } catch (err: any) {
      console.error("Error cancelling booking", err);
      setError(
        err?.response?.data?.message || "Failed to cancel booking."
      );
    } finally {
      setActionLoadingId(null);
    }
  };

  const handleReschedule = (booking: BookingCard) => {
    // We send the data needed to re-use the booking flow.
    // Adjust the route or state shape if your SelectDatePage expects something else.
    navigate("/select-date", {
      state: {
        businessId: booking.businessId,
        businessName: booking.salonName,
        selectedServices: booking.servicesRaw,
        isReschedule: true,
        bookingId: booking.id,
      },
    });
  };

  return (
    <PageWrapper>
      <TabBar type="customer" />

      <ContentWrapper>
        {/* UPCOMING */}
        <Section>
          <SectionTitle>Upcoming Bookings</SectionTitle>

          {loading && <EmptyText>Loading your bookings...</EmptyText>}
          {error && <ErrorText>{error}</ErrorText>}
          {!loading && !error && upcoming.length === 0 && (
            <EmptyText>No upcoming bookings found.</EmptyText>
          )}

          <TilesContainer>
            {upcoming.map((b) => (
              <BookingTile
                key={b.id}
                id={b.id}
                date={b.date}
                image={b.image}
                salonName={b.salonName}
                location={b.location}
                services={b.services}
                status={b.status}
                //disabled={actionLoadingId === b.id}
                onCancel={() => handleCancel(b)}
                onViewReceipt={() => navigate(`/bookings/${b.id}`)}
                onReschedule={() => handleReschedule(b)}
              />
            ))}
          </TilesContainer>
        </Section>

        {/* PAST */}
        <Section>
          <SectionTitle>Past Bookings</SectionTitle>

          {!loading && !error && past.length === 0 && (
            <EmptyText>No past bookings yet.</EmptyText>
          )}

          <TilesContainer>
            {past.map((b) => (
              <BookingTile
                key={b.id}
                id={b.id}
                date={b.date}
                image={b.image}
                salonName={b.salonName}
                location={b.location}
                services={b.services}
                status={b.status}
                onLeaveRating={() => alert("Add rating coming soon")}
                onViewReceipt={() => navigate(`/bookings/${b.id}`)}
              />
            ))}
          </TilesContainer>
        </Section>
      </ContentWrapper>
    </PageWrapper>
  );
};

export default BookingsPage;
